import copy
import json
import re
from pathlib import Path

ROOT = Path('/Volumes/YSAigc/\u5267\u4f5c\u9879\u76ee/\u6211\u4e0d\u518d\u505a\u6559\u7236\u7684\u5927\u7801\u4eba\u5f62\u62b1\u6795')
AUTH = ROOT / '\u590d\u523b\u5168\u96c6_FormatC_V25_20261022'
TASK = ROOT / '\u7b2c09\u7ec4_\u66a7\u6627\u8fd1\u666f\u4e0e\u6c89\u8ff7\u7279\u5199_20261023'
TASK.mkdir(exist_ok=True)
base = json.loads((AUTH / '\u590d\u523b\u5168\u96c6_FormatC_V25_\u5168\u90e8\u63d0\u793a\u8bcd.json').read_text())
draft = copy.deepcopy(base)
g = next(x for x in draft['groups'] if x['timeline_position'] == 9)
patches = []
for suffix in ['json', 'md']:
    name = '\u590d\u523b\u5168\u96c6_FormatC_V25_\u5168\u90e8\u63d0\u793a\u8bcd.' + suffix
    (TASK / ('\u4fee\u6539\u524d_' + name)).write_bytes((AUTH / name).read_bytes())


def patch(shot, prefix, new):
    lines = g['prompt'].splitlines()
    current = 0
    found = []
    for i, line in enumerate(lines):
        m = re.match(r'\u3010shot (\d+)', line)
        if m:
            current = int(m.group(1))
        if current == shot and line.startswith(prefix):
            found.append(i)
    assert len(found) == 1, (shot, prefix, found)
    i = found[0]
    old = lines[i]
    assert old != new and '\xa7ASSET:' not in old
    patches.append({'position': 9, 'shot': shot, 'old': old, 'new': new})
    lines[i] = new
    g['prompt'] = '\n'.join(lines)


